-- Validate, then constrain; never repair or reassign immutable ownership.
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificate_models r WHERE NOT ((r.current_revision_id IS NULL OR EXISTS (SELECT 1 FROM px_self_certificate_revisions p WHERE p.id=r.current_revision_id AND p.owner_account_id=r.owner_account_id)))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificate_models'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificate_revisions r WHERE NOT ((r.origin_model_id IS NULL OR EXISTS (SELECT 1 FROM px_self_certificate_models p WHERE p.id=r.origin_model_id AND p.owner_account_id=r.owner_account_id)) AND EXISTS (SELECT 1 FROM px_self_certificate_assets p WHERE p.id=r.background_asset_id AND p.owner_account_id=r.owner_account_id AND p.kind=''background'') AND (r.stamp_asset_id IS NULL OR EXISTS (SELECT 1 FROM px_self_certificate_assets p WHERE p.id=r.stamp_asset_id AND p.owner_account_id=r.owner_account_id AND p.kind=''stamp'')))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificate_revisions'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificate_links r WHERE NOT (EXISTS (SELECT 1 FROM px_self_certificate_revisions p WHERE p.id=r.revision_id AND p.owner_account_id=r.owner_account_id))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificate_links'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificate_requests r WHERE NOT (EXISTS (SELECT 1 FROM px_self_certificate_links p WHERE p.id=r.link_id AND p.owner_account_id=r.owner_account_id) AND EXISTS (SELECT 1 FROM px_self_certificate_revisions p WHERE p.id=r.revision_id AND p.owner_account_id=r.owner_account_id) AND EXISTS (SELECT 1 FROM px_self_certificate_links p WHERE p.id=r.link_id AND p.owner_account_id=r.owner_account_id AND p.revision_id=r.revision_id))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificate_requests'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificates r WHERE NOT (EXISTS (SELECT 1 FROM px_self_certificate_requests p WHERE p.id=r.request_id AND p.owner_account_id=r.owner_account_id) AND EXISTS (SELECT 1 FROM px_self_certificate_links p WHERE p.id=r.link_id AND p.owner_account_id=r.owner_account_id) AND EXISTS (SELECT 1 FROM px_self_certificate_assets p WHERE p.id=r.final_asset_id AND p.owner_account_id=r.owner_account_id AND p.kind=''final'') AND EXISTS (SELECT 1 FROM px_self_certificate_assets p WHERE p.id=r.thumbnail_asset_id AND p.owner_account_id=r.owner_account_id AND p.kind=''thumbnail'') AND EXISTS (SELECT 1 FROM px_self_certificate_requests p WHERE p.id=r.request_id AND p.owner_account_id=r.owner_account_id AND p.link_id=r.link_id))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificates'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificate_export_jobs r WHERE NOT ((r.asset_id IS NULL OR EXISTS (SELECT 1 FROM px_self_certificate_assets p WHERE p.id=r.asset_id AND p.owner_account_id=r.owner_account_id AND p.kind=''export'')))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificate_export_jobs'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF EXISTS (SELECT 1 FROM px_self_certificate_export_snapshot_rows r WHERE NOT (EXISTS (SELECT 1 FROM px_self_certificate_export_jobs p WHERE p.id=r.export_id AND p.owner_account_id=r.owner_account_id) AND EXISTS (SELECT 1 FROM px_self_certificate_requests p WHERE p.id=r.source_request_id AND p.owner_account_id=r.owner_account_id))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:px_self_certificate_export_snapshot_rows'' USING ERRCODE=''23514''; END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_assets''::regclass AND conname=''uq_self_asset_owner'') THEN ALTER TABLE px_self_certificate_assets ADD CONSTRAINT uq_self_asset_owner UNIQUE (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_models''::regclass AND conname=''uq_self_model_owner'') THEN ALTER TABLE px_self_certificate_models ADD CONSTRAINT uq_self_model_owner UNIQUE (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_revisions''::regclass AND conname=''uq_self_revision_owner'') THEN ALTER TABLE px_self_certificate_revisions ADD CONSTRAINT uq_self_revision_owner UNIQUE (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_links''::regclass AND conname=''uq_self_link_owner'') THEN ALTER TABLE px_self_certificate_links ADD CONSTRAINT uq_self_link_owner UNIQUE (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_links''::regclass AND conname=''uq_self_link_owner_revision'') THEN ALTER TABLE px_self_certificate_links ADD CONSTRAINT uq_self_link_owner_revision UNIQUE (owner_account_id,id,revision_id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_requests''::regclass AND conname=''uq_self_request_owner'') THEN ALTER TABLE px_self_certificate_requests ADD CONSTRAINT uq_self_request_owner UNIQUE (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_requests''::regclass AND conname=''uq_self_request_owner_link'') THEN ALTER TABLE px_self_certificate_requests ADD CONSTRAINT uq_self_request_owner_link UNIQUE (owner_account_id,id,link_id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_export_jobs''::regclass AND conname=''uq_self_export_owner'') THEN ALTER TABLE px_self_certificate_export_jobs ADD CONSTRAINT uq_self_export_owner UNIQUE (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_models''::regclass AND conname=''fk_self_model_revision_owner'') THEN ALTER TABLE px_self_certificate_models ADD CONSTRAINT fk_self_model_revision_owner FOREIGN KEY (owner_account_id,current_revision_id) REFERENCES px_self_certificate_revisions (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_revisions''::regclass AND conname=''fk_self_revision_background_owner'') THEN ALTER TABLE px_self_certificate_revisions ADD CONSTRAINT fk_self_revision_background_owner FOREIGN KEY (owner_account_id,background_asset_id) REFERENCES px_self_certificate_assets (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_revisions''::regclass AND conname=''fk_self_revision_stamp_owner'') THEN ALTER TABLE px_self_certificate_revisions ADD CONSTRAINT fk_self_revision_stamp_owner FOREIGN KEY (owner_account_id,stamp_asset_id) REFERENCES px_self_certificate_assets (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_links''::regclass AND conname=''fk_self_link_revision_owner'') THEN ALTER TABLE px_self_certificate_links ADD CONSTRAINT fk_self_link_revision_owner FOREIGN KEY (owner_account_id,revision_id) REFERENCES px_self_certificate_revisions (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_requests''::regclass AND conname=''fk_self_request_link_revision_owner'') THEN ALTER TABLE px_self_certificate_requests ADD CONSTRAINT fk_self_request_link_revision_owner FOREIGN KEY (owner_account_id,link_id,revision_id) REFERENCES px_self_certificate_links (owner_account_id,id,revision_id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificates''::regclass AND conname=''fk_self_issued_request_link_owner'') THEN ALTER TABLE px_self_certificates ADD CONSTRAINT fk_self_issued_request_link_owner FOREIGN KEY (owner_account_id,request_id,link_id) REFERENCES px_self_certificate_requests (owner_account_id,id,link_id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificates''::regclass AND conname=''fk_self_issued_final_owner'') THEN ALTER TABLE px_self_certificates ADD CONSTRAINT fk_self_issued_final_owner FOREIGN KEY (owner_account_id,final_asset_id) REFERENCES px_self_certificate_assets (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificates''::regclass AND conname=''fk_self_issued_thumbnail_owner'') THEN ALTER TABLE px_self_certificates ADD CONSTRAINT fk_self_issued_thumbnail_owner FOREIGN KEY (owner_account_id,thumbnail_asset_id) REFERENCES px_self_certificate_assets (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_export_jobs''::regclass AND conname=''fk_self_export_asset_owner'') THEN ALTER TABLE px_self_certificate_export_jobs ADD CONSTRAINT fk_self_export_asset_owner FOREIGN KEY (owner_account_id,asset_id) REFERENCES px_self_certificate_assets (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_export_snapshot_rows''::regclass AND conname=''fk_self_snapshot_export_owner'') THEN ALTER TABLE px_self_certificate_export_snapshot_rows ADD CONSTRAINT fk_self_snapshot_export_owner FOREIGN KEY (owner_account_id,export_id) REFERENCES px_self_certificate_export_jobs (owner_account_id,id); END IF; END;';
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''px_self_certificate_export_snapshot_rows''::regclass AND conname=''fk_self_snapshot_source_owner'') THEN ALTER TABLE px_self_certificate_export_snapshot_rows ADD CONSTRAINT fk_self_snapshot_source_owner FOREIGN KEY (owner_account_id,source_request_id) REFERENCES px_self_certificate_requests (owner_account_id,id); END IF; END;';
CREATE OR REPLACE FUNCTION owner_chain_models() RETURNS trigger AS 'BEGIN IF NOT ((NEW.current_revision_id IS NULL OR EXISTS (SELECT 1 FROM px_self_certificate_revisions p WHERE p.id=NEW.current_revision_id AND p.owner_account_id=NEW.owner_account_id))) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_OWNER_CHAIN_INVALID'' USING ERRCODE=''23514''; END IF; RETURN NEW; END;' LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS owner_chain_models ON px_self_certificate_models;
CREATE TRIGGER owner_chain_models BEFORE INSERT OR UPDATE ON px_self_certificate_models FOR EACH ROW EXECUTE FUNCTION owner_chain_models();
